#!/usr/bin/env python3
"""Regenerate the vendored bare_proc parser after changing its release or patch.

Only `src/parser.rs`, `src/grammar.pest` and `LICENSE` are taken from the
upstream crate. The patch in `patches/` is applied with `--fuzz=0`, then an
attribution header is prepended, so the patch never contains the header.

Editing workflow:

    ./regenerate.py --extract /tmp/bare_proc-edit     # patched sources, no header
    $EDITOR /tmp/bare_proc-edit/parser.rs
    ./regenerate.py --write-patch /tmp/bare_proc-edit # rewrite the patch
    ./regenerate.py                                   # regenerate src/bare_proc
"""

import argparse
import hashlib
import io
import os
from pathlib import Path
import shutil
import subprocess
import tarfile
import tempfile
import urllib.request

VERSION = "0.2.0"
SHA256 = "3fcefd4af8e8e039181a31d7bff70e1fa5c22d6b7efffb485496f3197bf7b27e"
URL = f"https://static.crates.io/crates/bare_proc/bare_proc-{VERSION}.crate"
UPSTREAM = "https://git.sr.ht/~chiefnoah/bare_proc"

DIRECTORY = Path(__file__).resolve().parent
CRATE = DIRECTORY.parents[1]
PATCH = DIRECTORY / "patches" / f"bare_proc-{VERSION}-vbare.patch"
DESTINATION = CRATE / "src" / "bare_proc"
LICENSE = CRATE / "LICENSE-bare_proc"

# Upstream path inside the crate archive, mapped to the vendored file name.
FILES = {
    "src/parser.rs": "parser.rs",
    "src/grammar.pest": "grammar.pest",
}

HEADER = (
    f"// Vendored from bare_proc {VERSION} ({UPSTREAM}), MIT license; see LICENSE-bare_proc.\n"
    f"// Generated by vendor/bare_proc/regenerate.py from the upstream release and\n"
    f"// vendor/bare_proc/patches/bare_proc-{VERSION}-vbare.patch. Do not edit by hand.\n"
)


def download(archive):
    if archive:
        data = archive.read_bytes()
    else:
        with urllib.request.urlopen(URL, timeout=60) as response:
            data = response.read()
    if hashlib.sha256(data).hexdigest() != SHA256:
        raise RuntimeError(f"checksum mismatch for bare_proc {VERSION}")
    return data


def extract(data, staging):
    """Extract the pristine crate into `staging` and return its root."""
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
        archive.extractall(staging, filter="data")
    return staging / f"bare_proc-{VERSION}"


def apply_patch(source):
    subprocess.run(
        ["patch", "--batch", "--forward", "--fuzz=0", "-p1"],
        input=PATCH.read_bytes(),
        cwd=source,
        check=True,
        stdout=subprocess.DEVNULL,
    )


def strip_header(text):
    return text[len(HEADER) :] if text.startswith(HEADER) else text


def write_patch(data, edited):
    """Diff the pristine sources against the edited copies in `edited`."""
    with tempfile.TemporaryDirectory(prefix=".bare_proc-") as temp:
        source = extract(data, Path(temp))
        chunks = []
        for upstream, name in FILES.items():
            edited_file = Path(temp) / f"edited-{name}"
            edited_file.write_text(strip_header((edited / name).read_text()))
            result = subprocess.run(
                [
                    "diff",
                    "-u",
                    "--label",
                    f"a/{upstream}",
                    "--label",
                    f"b/{upstream}",
                    str(source / upstream),
                    str(edited_file),
                ],
                capture_output=True,
                text=True,
            )
            # diff exits with 1 when the files differ and 2 on trouble.
            if result.returncode > 1:
                raise RuntimeError(result.stderr)
            chunks.append(result.stdout)
    PATCH.write_text("".join(chunks))
    print(f"Wrote {PATCH.relative_to(CRATE)}")


def regenerate(data, extract_to):
    DESTINATION.parent.mkdir(parents=True, exist_ok=True)
    # Prepare and patch in isolation, so a failed download or patch leaves the
    # existing vendored tree untouched.
    with tempfile.TemporaryDirectory(prefix=".bare_proc-", dir=DESTINATION.parent) as temp:
        staging = Path(temp)
        source = extract(data, staging)
        apply_patch(source)

        if extract_to:
            extract_to.mkdir(parents=True, exist_ok=True)
            for upstream, name in FILES.items():
                shutil.copyfile(source / upstream, extract_to / name)
            print(f"Extracted patched bare_proc {VERSION} sources to {extract_to}")
            return

        output = staging / "out"
        output.mkdir()
        for upstream, name in FILES.items():
            text = (source / upstream).read_text()
            (output / name).write_text(HEADER + text)
        license_tmp = staging / "LICENSE"
        shutil.copyfile(source / "LICENSE", license_tmp)

        # Keep the old tree until its replacement is ready, including on rename failure.
        previous = staging / "previous"
        if DESTINATION.exists():
            DESTINATION.rename(previous)
        try:
            output.rename(DESTINATION)
        except OSError:
            if previous.exists():
                previous.rename(DESTINATION)
            raise
        os.replace(license_tmp, LICENSE)

    print(f"Regenerated bare_proc {VERSION} in {DESTINATION.relative_to(CRATE)}")


def main():
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("--archive", type=Path, help="use a local .crate archive for offline setup")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--extract", type=Path, metavar="DIR", help="write the patched sources to DIR for editing")
    mode.add_argument("--write-patch", type=Path, metavar="DIR", help="rewrite the patch from edited sources in DIR")
    args = parser.parse_args()

    data = download(args.archive)
    if args.write_patch:
        write_patch(data, args.write_patch)
    else:
        regenerate(data, args.extract)


if __name__ == "__main__":
    main()
